function IconButton({icon:Icon,onClick,title,children,danger=false}){return <button type="button" title={title} aria-label={title||'Tugma'} className={`icon-btn ${danger?'icon-btn--danger':''}`} onClick={onClick}>{Icon&&<Icon size={17}/>} {children}</button>}
function Button({icon:Icon,children,onClick,variant='primary',type='button',disabled=false}){return <button type={type} disabled={disabled} onClick={onClick} className={`btn btn--${variant}`}>{Icon&&<Icon size={17} strokeWidth={2.1}/>} {children}</button>}
function Empty({icon:Icon=CircleHelp,title='Ma’lumot topilmadi',detail='Filtrni o‘zgartiring yoki yangi ma’lumot qo‘shing.',action}){return <div className="empty"><div className="empty__icon"><Icon size={25}/></div><h3>{title}</h3><p>{detail}</p>{action}</div>}
function PageIntro({eyebrow,title,description,children}){return <div className="page-intro"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description&&<p>{description}</p>}</div><div className="page-intro__actions">{children}</div></div>}
function Card({children,className=''}){return <div className={`card ${className}`}>{children}</div>}
function SectionTitle({children,sub,action}){return <div className="section-head"><div><h3>{children}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>}
function Kpi({icon:Icon,label,value,delta,sub,tone='teal',onClick}){return <div className={`kpi kpi--${tone} ${onClick?'kpi--click':''}`} onClick={onClick} role={onClick?'button':undefined} tabIndex={onClick?0:undefined} onKeyDown={e=>onClick&&e.key==='Enter'&&onClick()}><div className="kpi__top"><span>{label}</span><div className="kpi__icon"><Icon size={18}/></div></div><strong>{value}</strong><div className="kpi__bottom">{delta&&<span className="kpi__trend">{delta}</span>}{sub&&<span>{sub}</span>}</div></div>}
function TextInput({value,onChange,placeholder='',type='text',min,step,required=false}){return <input required={required} type={type} min={min} step={step} className="field-control" value={value??''} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>}
function Select({value,onChange,options,placeholder='Tanlang',required=false}){return <select required={required} className="field-control" value={value??''} onChange={e=>onChange(e.target.value)}><option value="">{placeholder}</option>{options.map(o=>{let option=typeof o==='string'?{value:o,label:o}:o;return <option key={option.value} value={option.value}>{option.label}</option>})}</select>}
function Field({label,desc,wide=false,children}){return <label className={`form-field ${wide?'form-field--wide':''}`}><span>{label}</span>{children}{desc&&<small>{desc}</small>}</label>}
function Modal({title,subtitle,onClose,children,wide=false}){useEffect(()=>{const onKey=e=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',onKey);document.body.classList.add('modal-open');return()=>{window.removeEventListener('keydown',onKey);document.body.classList.remove('modal-open')}},[onClose]);return <div className="overlay" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'modal--wide':''}`}><div className="modal__header"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><IconButton icon={X} onClick={onClose} title="Yopish"/></div>{children}</div></div>}
function Confirm({item,onCancel,onConfirm}){return <Modal title={item.title||'Tasdiqlash'} subtitle={item.detail||'Bu amalni orqaga qaytarib bo‘lmaydi.'} onClose={onCancel}><div className="modal__footer"><Button variant="outline" onClick={onCancel}>Bekor qilish</Button><Button onClick={onConfirm} variant="danger">{item.button||'O‘chirish'}</Button></div></Modal>}
function FallbackLine({text}){return <span className="muted">{text||'—'}</span>}
function TableShell({heads,children,empty=false,emptyTitle='Ma’lumot yo‘q'}){return <div className="table-wrap"><table><thead><tr>{heads.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{children}</tbody></table>{empty&&<Empty title={emptyTitle}/>}</div>}
function MiniProgress({percent,tone='teal'}){return <div className={`mini-progress mini-progress--${tone}`}><span style={{width:`${Math.min(100,Math.max(0,percent))}%`}}/></div>}
function Loading(){return <div className="loading-screen"><LoaderCircle className="spin" size={32}/><strong>AutoSchool yuklanmoqda...</strong><span>Mahalliy ma’lumotlar bazasiga ulanish</span></div>}
const csv=(name,headers,rows)=>{const esc=v=>{const text=String(v??'');return `"${(/^[=+@-]/.test(text)?'\t':'')+text.replace(/"/g,'""')}"`};const out='\uFEFF'+[headers,...rows].map(r=>r.map(esc).join(';')).join('\r\n'); const url=URL.createObjectURL(new Blob([out],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
const downloadJSON=(name,data)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
